import { Request, Response, NextFunction } from "express";
import { supabase } from "../supabase";

export interface AuthenticatedUser {
  id: string;
  email: string;
  role: "admin" | "client" | "driver";
  vipTier?: string;
  fullName?: string;
  provider?: string;
}

// Extend Express Request type
declare global {
  namespace Express {
    interface Request {
      user?: AuthenticatedUser;
    }
  }
}

/**
 * Middleware: Verifies Supabase JWT access token (Generated by Google OAuth or Email Login)
 */
export async function requireAuth(req: Request, res: Response, next: NextFunction) {
  try {
    const authHeader = req.headers.authorization;
    if (!authHeader || !authHeader.startsWith("Bearer ")) {
      return res.status(401).json({ error: "Missing or invalid authorization token" });
    }

    const token = authHeader.split(" ")[1];

    // Verify token with Supabase Auth
    const { data: { user }, error } = await supabase.auth.getUser(token);

    if (error || !user) {
      return res.status(401).json({ error: "Invalid or expired session token" });
    }

    // Fetch user profile from public.profiles
    const { data: profile } = await supabase
      .from("profiles")
      .select("role, full_name, vip_tier")
      .eq("id", user.id)
      .maybeSingle();

    req.user = {
      id: user.id,
      email: user.email || "",
      // HARDENED: Authoritative role from database; NEVER trust client-writable user_metadata
      role: profile?.role || "client",
      vipTier: profile?.vip_tier || "standard",
      fullName: profile?.full_name || user.user_metadata?.full_name || user.user_metadata?.name || "Client",
      provider: user.app_metadata?.provider || "email",
    };

    next();
  } catch (err: any) {
    return res.status(500).json({ error: "Authentication verification failed", details: err.message });
  }
}

/**
 * Middleware: Requires admin privileges
 */
export async function requireAdmin(req: Request, res: Response, next: NextFunction) {
  await requireAuth(req, res, () => {
    if (req.user?.role !== "admin") {
      return res.status(403).json({ error: "Forbidden: Admin privileges required" });
    }
    next();
  });
}
